payload.summary:
cd /work/wt89 && git checkout -q --detach 89575bfa && cat > packages/std-avrac/src/compiler/tests/probe_rx_test.av <<'EOF'
use @std.avrac.testing.held.{held_at}

describe "probe" {
    given "rx" {
        then "says" {
            let j = held_at(
                {
                    "/w/avra.toml": "[package]\nname = \"reexport\"\nversion = \"0.1.0\"\n",
                    "/w/src/schema.av": "export type Ref = { id: string }\n",
                    "/w/src/api.av": "export use schema.{Ref}\n",
                    "/w/src/main.av": "use schema.{Ref}\nlet r = Ref { id: \"a\" }\nprintln(r.id)\n",
                },
                "/w",
            )
                .judged_at("/w/src/main.av")
            "[${j.diagnostics.length}] ${j.report()}" == "x"
        }
    }
}
EOF
. /etc/profile.d/avra.sh; timeout 1500 /work/avra/build/avra test packages/std-avrac/src/compiler/tests/probe_rx_test.av 2>&1 | grep -v "^warning" | sed -n '/actual/,/expected/p' | head -20

