    fn bind_weakly(d: DeclId, base: BoundNames) {
        let x = self.decls.decl(d)
        let space? = table_of(x.kind) else { return }
        if self.held(x.kind, x.name) == null && held_in(base, space, x.name) == null { self.bind(x.kind, x.name, d) }
