    /// and a re-export, claiming the name for the module, does not. A name
    /// the module already refused as declared twice (`refused`) is that
    /// refusal's: its clash with an import is no second finding.
    fn import(i: Import, file: FileId, base: BoundNames, refused: List<string>) {
        let x = self.decls.decl(i.decl)
        // A `use` item's ALIAS is the name it binds under; the empty
        // alias is the declaration's own name.
        let name = if i.renamed.is_empty() { x.name } else { i.renamed }
        let prior? = self.held(x.kind, name) ?? self.claimed(base, x.kind, name, file, i.shared) else { return self.bind(x.kind, name, i.decl) }
        if same_decl(prior, i.decl) || refused.contains(name) { return }
        self.speak(import_clash(i.at, name, self.holder(prior, file)))
    }

    /// The module's holder of a name as `file` sees it claimed: an
    /// export, or this file's own — a sibling's private declaration
    /// claims nothing here, unless the import claims the name itself.
    fn claimed(base: BoundNames, kind: DeclKind, name: string, file: FileId, shared: bool) -> DeclId? {
        let space? = table_of(kind) else { return null }
        let d? = held_in(base, space, name) else { return null }
        let x = self.decls.decl(d)
        if shared || x.exported || same_file(x.file, file) { d } else { null }
    }

    /// Who holds a name already: this module (by file), or a module.
    fn holder(prior: DeclId, file: FileId) -> string {
        let p = self.decls.decl(prior)
