    }

    fn held(kind: DeclKind, name: string) -> DeclId? {
        let space? = table_of(kind) else { return null }
        match space {
            .Fn -> self.names.fns.get(name),
            .Type -> self.names.types.get(name),
            .Syntax -> self.names.syntaxes.get(name),
        }
}

fn kept_apart_read(at: Loc?, name: string, files: List<string>) -> Diag { said_as("resolve.kept_apart", at, apart_read(name, files)) }

/// A read of `name`, which each of `files` declares privately, so none of them shares it.
export fn apart_read(name: string, files: List<string>) -> Voice {
    Voice {
        message: "`${name}` is private to each of ${joined(["`${f}`" for f in files], " and ")} — a private name two files declare is each file's own",
        label: "read here",
        help: "`export` one declaration to share it across the module, or declare this file's own",
    }
}

fn import_clash(at: Loc?, item: string, holder: string) -> Diag { said_as("resolve.import_clash", at, import_clashed(item, holder)) }

/// An import of `item`, whose name `holder` already binds.
export fn import_clashed(item: string, holder: string) -> Voice {
    Voice {
        message: "`${item}` is imported, but ${holder} already has it",
        label: "in this use",
        help: "drop the import, or rename the local declaration",
    }
}
const EXPORTS_F: string = "export fn f() -> int { 1 }\n"

/// a module is a directory or a file, not both
export law use_names_one_module {
    kind: "resolve.module_ambiguous"
    reads: twofold_uses
    voice: twofold_words
    witness: "use util.{f}\n1\n"
    witness_files: {"src/util.av": EXPORTS_F, "src/util/mod.av": "export fn g() -> int { 1 }\n"}
}

/// a `use` names a module the source root holds
export law use_names_a_module {
    kind: "resolve.no_module"
    reads: moduleless_uses
    voice: moduleless_words
    witness: "use nope.{x}\n1\n"
}

/// a `use` lists each name once
export law use_lists_once {
    kind: "resolve.import_clash"
    reads: listed_uses
    voice: listed_words
    witness: "use util.{f, f}\nf()\n"
    witness_files: {"src/util.av": EXPORTS_F}
}

/// a `use` binds a name no `use` before it bound to another declaration
export law use_binds_a_name_once {
    kind: "resolve.import_clash"
    reads: clashing_uses
    voice: clashing_words
    witness: "use util.{f}\nuse other.{f}\nf()\n"
    witness_files: {"src/util.av": EXPORTS_F, "src/other.av": EXPORTS_F}
}

fn clashing_words(a: List<string>) -> Voice { import_clashed(a[1], "`${a[2]}`") }

/// a `use` names what its module exports
export law use_names_an_export {
    kind: "resolve.not_exported"
    reads: unexported_uses
    voice: unexported_words
    witness: "use util.{hidden}\n1\n"
    witness_files: {"src/util.av": "fn hidden() -> int { 1 }\n"}

