// The module system under attack (rt33): names against names across
// files, every misuse of `export` and `use`, impls that cross a
// module's line, and the crossings that must simply work. The
// vertical story lives in workspace_test.av; these are the programs
// that tried to break it.
use @std.avrac.testing.{judged}
use @std.avrac.testing.held.{Held, Judged, held_at}

/// The files among `files` a host lists by `names` — what the program can see — under the
/// package's manifest.
fn listed(files: Map<string, string>, names: List<string>) -> Map<string, string> {
    mut held: Map<string, string> = {}
    for path in names { held.set(path, files.get(path) ?? "") }
    if !held.has(MANIFEST) { held.set(MANIFEST, "[package]\nname = \"app\"\nversion = \"0.1.0\"\n") }
    held
}

/// Where the package under attack keeps its manifest: a package has one.
const MANIFEST: string = "/w/avra.toml"

/// A root file plus whatever the attack adds.
fn package(files: Map<string, string>, names: List<string>) -> Held {
    held_at(listed(files, names), "/w")
}

/// The root file's ONE refusal, saying this.
fn refuses_once(files: Map<string, string>, names: List<string>, saying: string) -> bool {
    let a = package(files, names).judged_at("/w/src/main.av")
    a.diagnostics.length == 1 && a.report().contains(saying)
}

fn runs(files: Map<string, string>, names: List<string>) -> string? {
    match package(files, names).judged_at("/w/src/main.av").run() {
        .Ok(text) -> text,
        .Err(_) -> null,
    }
}

/// One file's analysis in the package `files` holds.
fn analysed_at(files: Map<string, string>, names: List<string>, at: string) -> Judged {
    package(files, names).judged_at(at)
}

/// A test file's own helper, the name every attack below reuses.
fn thing() -> string {
    "fn make_thing() -> int {\n    1\n}\n"
}

