'''/// Every arm of the written item `view` shows whose pattern an earlier unguarded arm's format
/// accepts every text of — `format_subsumes` answering that it covers — found where it stands; handed
/// the earlier pattern as written.
fn formats_covered(view: ItemView) -> List<Found> {
    let store = view.item.store
    let written_only = template_nodes(store)
    let signing = Signing { engine: view.engine, file: view.file, type_params: [] }
    [f! for i in 0..store.exprs.count() for e in [ExprId { index: i }] if !written_only.contains(e) for m in some_list(match_at(store, e)) for j in 0..m.arms.length for f in [covered_arm(store, signing, m.arms, j)] if f != null]
}

/// The arm `j` of `arms` where an earlier unguarded arm's format covers its pattern: found at its
/// pattern, handed the earlier one; absent where none does or none can be told to.
fn covered_arm(store: SyntaxArena, signing: Signing, arms: List<MatchArm>, j: int) -> Found? {
    if arms[j].pats.length != 1 { return null }
    let b? = pat_shape(store, signing, arms[j].pats[0]) else { return null }
    let k? = (0..j).find((i) -> arms[i].guard == null && arms[i].pats.length == 1 && shape_covers(store, signing, arms[i].pats[0], b)) else { return null }
    Found { at: store.pat_span(arms[j].pats[0]), args: [pattern_spelled(store, arms[k].pats[0])] }
}

/// Whether the pattern `p` is a format that accepts every text `b` does.
fn shape_covers(store: SyntaxArena, signing: Signing, p: PatId, b: FormatShape) -> bool {
    let a? = pat_shape(store, signing, p) else { return false }
    format_subsumes(a, b) is .Covers
}

/// The shape of the pattern `p` where it is a format or a text literal; absent for any other.
fn pat_shape(store: SyntaxArena, signing: Signing, p: PatId) -> FormatShape? {
    match store.pat(p) {
        .Format(head, parts) -> {
            let format = GrammarSpec { head: head, parts: parts }
            format_shape(format, readings_of(format, signing))
        },
        .Lit(v) -> {
            let text? = store.expr(v).text_of() else { return null }
            FormatShape { head: text, holes: [] }
        },
        rest -> null,
    }
}

/// The pattern `p`, a format or a text literal, as it is written.
fn pattern_spelled(store: SyntaxArena, p: PatId) -> string {
    match store.pat(p) {
        .Format(head, parts) -> "\\"${pattern_text(head, parts)}\\"",
        .Lit(v) -> "\\"${store.expr(v).text_of() ?? ""}\\"",
        rest -> "",
    }
}

/// an arm after a format that accepts every text it does
export law arm_after_format {
    kind: "type.unreachable_arm"
    reads_view: formats_covered
    voice: format_arm_words
    warns: true
    witness: "fn f(t: string) -> int {\\n    match t {\\n        \\"/a/{x}\\" -> 1,\\n        \\"/a/b\\" -> 2,\\n        _ -> 3,\\n    }\\n}\\n"
}

fn format_arm_words(a: List<string>) -> Voice { format_covers_arm(a[0]) }

fn binder_words(a: List<string>) -> Voice { unreached_after_binder_said(a[0]) }'''),
])
