/// A declared name's shape, read from its declaration.
export fn named_shape(n: string) -> NamedShape {
    let ty? = type_named(n) else { return NamedShape.Plain }
    shape_of(ty)
}

/// A name as a query's seat or answer is carried: a type that holds its own codec crosses by it,
/// whatever its fields; any other by its shape.
export fn coded_shape(n: string) -> NamedShape {
    if wears_codec(n) { return NamedShape.Tagged([]) }
    named_shape(n)
}
}

/// Whether a shape is one a scope spells, so a wire reaching it is handed the scope.
fn crosses_by_scope(shape: NamedShape) -> bool {
    match shape { .Dense(_) or .Placed(_) -> true, rest -> false }
}

/// A reached declaration: the type itself, or one the compiler names.
fn stored_type(t: Type, n: string) -> Type? { if n == t.name { t } else { type_named(n) } }

/// The helpers a stored type writes and reads by: one set for every kind its wire reaches.
fn stored_helpers(s: Stored, inner: List<Kind>) -> List<Decls> {
    [d for k in inner for d in helper_members(s.t, k, s.owner, !s.owner.scoped)]
}

/// The records and payload enums a stored type's wire reaches: itself among them when it is
/// an enum, or a record that reaches itself.
fn stored_within(s: Stored) -> List<Kind> {
    if s.t.variants.is_empty() { reached_kinds(s.wire, [], true) } else { s.reached }
}

/// Whether a declaration carries its own codec — `@codec` gives a record or an enum the write,
/// read and hash its own `impl` holds, so a stored answer needs no second generator.
fn wears_codec(n: string) -> bool {
    let t? = type_named(n) else { return false }
    t.annotations.any((a: Annotation) -> a.name == "codec")
}

/// Whether every named type this kind's hash and record reach declares `@codec`. A payload enum
/// and a record that reaches itself are called by name, so their type must hold the members.
fn codec_declared(k: Kind, seen: List<string>) -> bool { codec_declared_under(k, seen) }
