[package]
name        = "codec_reach_own_file"
version     = "0.0.1"
description = "A nested coded type's reaches resolve from its own file"

[bin]
name = "codec_reach_own_file"
path = "src/main.av"
use @std.relation.{Storable, codec}
use @std.relation.shape.{Form, descriptor_unspelled}
use limbs.{Limb}

@codec
type Stem = { l: Limb }

let d = descriptor_unspelled(Stem.codec_descriptor())!
let header = match d.reached.find(it.name == "Limb")?.form ?? Form.Unsaid {
    .Coded(h, _, _) -> h,
    .Unsaid or .Record or .Variants or .Over or .Dense -> 0,
}
println("Limb's own header:          ${Limb.codec_shape()}")
println("Stem's record of it:        ${header}")
println("types Stem's descriptor names: ${[r.name for r in d.reached].join(", ")}")
use @std.relation.{Storable, codec}

type Twig = { x: int }

@codec
export type Limb = { t: Twig }
closed_reached
closed_unreached

