use @std.meta.{Type, Field, Diagnostic, Declared, Directive, refuse_as_at}

/// Reads its marks and says them back, so the words that arrived are visible.
export trait Tagged {
    static fn derive(t: Type) -> List<Directive> { [] }
    static fn marks(t: Type) -> List<string> { ["tag"] }
}

export fn tagged(t: Type) -> Declared {
    let seen = [
        "${f.name}: ${m.args.join(",")} | ${[a.label + "=" + a.value for a in m.named].join(",")}" for f in t.fields for m in f.marks
    ]
    Declared { made: Tagged.derive(t), problems: [refuse_as_at("seen", t.at, "field marks: " + seen.join("; "), null)] }
}

/// A type-level annotation over the type's own fields, as `@unique(a, b)` is.
export fn tag(t: Type, ..fields: List<Field>) -> List<Diagnostic> {
    let named = [a for a in t.annotations if a.name == "tag"]
    [refuse_as_at("seen_type", t.at, "type tag fields: ${[f.name for f in fields].join(",")} | ${[x.label + "=" + x.value for a in named for x in a.named].join(",")}", null)]
}
