/// The static `Frame` a body's unwind pushes: its `{label, loc}` laid
/// out as the binary's data, one per body. The label is the name a
/// reader knows the body by, the loc the place it was written.
fn body_frame(a: Analysis, sym: string, label: string, file: FileId, body: IndexRange) -> BodyFrame {
    let site = StaticBox
        .Slots([Slot.Text(a.view.decls.file_named(file)), Slot.Int(body.lo), Slot.Int(body.hi)])
    BodyFrame {
        sym: "frame\$${sym}",
        boxes: [site, StaticBox.Slots([Slot.Text(label), Slot.Box(0)])],
    }
}

